from pathlib import Path
p=Path('runtime-src/companion-runtime.pyw')
s=p.read_text(encoding='utf-8')
s=s.replace('API_VERSION = 8','API_VERSION = 9',1)
anchor='    def import_url(self, url: str, character_id: str, categories: list[str]) -> tuple[dict[str, Any], bool]:\n'
if anchor not in s: raise SystemExit('anchor missing')
method='''    def import_fast_file(self, temp_path: Path, sha256: str, original_name: str, character_id: str, categories: list[str], content_type: str | None) -> tuple[dict[str, Any], bool]:\n        make_thumb = None\n        with self.lock:\n            c = self.character(character_id)\n            if not c: raise KeyError("Character not found")\n            categories = self._validate_categories(character_id, categories)\n            for existing in self.data["media"]:\n                if existing.get("character_id") == character_id and existing.get("sha256") == sha256:\n                    if existing.get("media_type") != "video":\n                        merged = list(dict.fromkeys(existing.get("categories", []) + categories))\n                        if merged != existing.get("categories", []):\n                            existing["categories"] = merged\n                            self.save()\n                    temp_path.unlink(missing_ok=True)\n                    return json.loads(json.dumps(existing)), True\n            media_id = uuid.uuid4().hex\n            original_name = safe_component(Path(original_name).name, f"media-{media_id}")\n            if not Path(original_name).suffix:\n                original_name += mimetypes.guess_extension((content_type or "").split(";")[0].strip()) or ""\n            if not content_type:\n                content_type = mimetypes.guess_type(original_name)[0] or "application/octet-stream"\n            media_type = "video" if content_type.startswith("video/") else "image"\n            if media_type == "video": categories = []\n            folder = self.media_dir / safe_component(c["name"], "Character")\n            folder.mkdir(parents=True, exist_ok=True)\n            dest = folder / f"{media_id}_{original_name}"\n            shutil.move(str(temp_path), dest)\n            item = {"id":media_id,"character_id":character_id,"original_name":original_name,"stored_rel":dest.relative_to(self.root).as_posix(),"thumb_rel":None,"media_type":media_type,"content_type":content_type,"categories":categories,"favorite":False,"in_review":False,"crop_top":0.0,"crop_bottom":0.0,"sha256":sha256,"source":{"kind":"local","original_name":original_name},"video_markers":[None,None,None],"video_thumb_seconds":0.0 if media_type == "video" else None,"created_at":now_iso()}\n            self.data["media"].append(item)\n            self.save()\n            if media_type == "image": make_thumb = media_id\n            result = json.loads(json.dumps(item))\n        if make_thumb:\n            threading.Thread(target=self._finish_fast_thumbnail,args=(make_thumb,),daemon=True).start()\n        return result, False\n\n    def _finish_fast_thumbnail(self, media_id: str) -> None:\n        try:\n            with self.lock:\n                m=self.media_item(media_id)\n                if not m or m.get("thumb_rel"): return\n                c=self.character(m.get("character_id", ""))\n                if not c: return\n                original=self.root / m["stored_rel"]\n                name=c["name"]\n            rel=self._make_thumbnail(original, media_id, name)\n            if not rel: return\n            with self.lock:\n                m=self.media_item(media_id)\n                if m:\n                    m["thumb_rel"]=rel\n                    self.save()\n        except Exception:\n            pass\n\n'''
s=s.replace(anchor,method+anchor,1)
route_anchor='            if path == "/api/import/file":\n'
if route_anchor not in s: raise SystemExit('route missing')
route='''            if path == "/api/import/fast":\n                parsed=urllib.parse.urlparse(self.path)\n                q=urllib.parse.parse_qs(parsed.query)\n                character_id=str((q.get("character_id") or [""])[0])\n                filename=str((q.get("filename") or ["upload"])[0])\n                try: categories=json.loads(str((q.get("categories") or ["[]"])[0]))\n                except Exception: categories=[]\n                if not isinstance(categories,list): categories=[]\n                content_type=(self.headers.get("Content-Type","") or "").split(";",1)[0].strip().lower()\n                if not content_type.startswith(("image/","video/")):\n                    content_type=mimetypes.guess_type(filename)[0] or content_type\n                if not (content_type or "").startswith(("image/","video/")): raise ValueError("Only image and video files are supported")\n                length=int(self.headers.get("Content-Length","0") or "0")\n                if length <= 0 or length > 600*1024*1024: raise ValueError("Upload size is invalid or exceeds 600 MB")\n                temp_dir=self.store.root / ".incoming"\n                temp_dir.mkdir(parents=True,exist_ok=True)\n                temp=temp_dir / f"{uuid.uuid4().hex}.part"\n                h=hashlib.sha256(); remaining=length\n                started=time.perf_counter()\n                try:\n                    with temp.open("wb") as out:\n                        while remaining:\n                            chunk=self.rfile.read(min(1024*1024,remaining))\n                            if not chunk: raise ValueError("Upload ended early")\n                            out.write(chunk); h.update(chunk); remaining-=len(chunk)\n                    receive_ms=round((time.perf_counter()-started)*1000)\n                    t=time.perf_counter()\n                    item,duplicate=self.store.import_fast_file(temp,h.hexdigest(),filename,character_id,categories,content_type)\n                    register_ms=round((time.perf_counter()-t)*1000)\n                    self._send_json(200,{"item":item,"duplicate":duplicate,"timing":{"receive_ms":receive_ms,"register_ms":register_ms,"bytes":length}})\n                except Exception:\n                    temp.unlink(missing_ok=True)\n                    raise\n                return\n'''
s=s.replace(route_anchor,route+route_anchor,1)
p.write_text(s,encoding='utf-8')
print('patched runtime v2.7.4')
